import {targetMask} from './damage-mask.js';
const $=id=>document.getElementById(id),photo=$('photo'),canvas=$('mask'),status=$('status');let worker,ready=false,url,timeout,started;
function show(){clearTimeout(timeout);canvas.style.display='block';if(!$('hold').checked)timeout=setTimeout(()=>canvas.style.display='none',240);}
$('flash').onclick=show;$('hold').onchange=()=>{$('hold').checked?show():canvas.style.display='none';};
$('file').onchange=()=>{if(url)URL.revokeObjectURL(url);const file=$('file').files[0];if(!file)return;url=URL.createObjectURL(file);photo.src=url;canvas.style.display='none';$('flash').disabled=true;status.textContent='Loading body mask…';
 if(!worker){worker=new Worker(new URL('./damage-mask-worker.js',import.meta.url));worker.onmessage=({data})=>{if(data.type==='ready'){ready=true;status.textContent='Tap the target’s face.';}else if(data.type==='mask'){const pixels=targetMask(data.confidence,data.width,data.height,worker.face);canvas.width=data.width;canvas.height=data.height;canvas.getContext('2d').putImageData(new ImageData(pixels,data.width,data.height),0,0);const covered=pixels.filter((v,i)=>i%4===3&&v>0).length;status.textContent=covered?`Body mask ready · ${Math.round(performance.now()-started)} ms · 50% red tint`:'No person mask at that point. Try the centre of the face.';$('flash').disabled=!covered;if(covered)show();}else if(data.type==='error')status.textContent='Body mask unavailable in this browser.';};worker.onerror=()=>status.textContent='Body mask could not load.';worker.postMessage({type:'init'});}else if(ready)status.textContent='Tap the target’s face.';
};
photo.onclick=async e=>{if(!ready||!photo.complete)return;const rect=photo.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width,y=(e.clientY-rect.top)/rect.height,scale=Math.min(1,512/photo.naturalHeight),scratch=document.createElement('canvas');scratch.width=Math.round(photo.naturalWidth*scale);scratch.height=Math.round(photo.naturalHeight*scale);scratch.getContext('2d').drawImage(photo,0,0,scratch.width,scratch.height);worker.face={x:(x-.04)*scratch.width,y:(y-.025)*scratch.height,width:.08*scratch.width,height:.05*scratch.height};started=performance.now();status.textContent='Finding the body silhouette…';const bitmap=await createImageBitmap(scratch);worker.postMessage({type:'frame',id:'preview',bitmap},[bitmap]);};
